{
  "criteria": [
    {
      "id": "C1",
      "level": "Accomplished",
      "mark": 7,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "The satellite, nicknamed ZYZZsat (Z-axis/Y-axis Zeroed Zoning Satellite), is operated and accessed from Australia ground facilities"
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required. This also just allows for simplicity in communications, reduces cost, and requires less time to build and launch."
        },
        {
          "where": "Introduction",
          "quote": "The proposed satellite would likely be used by governmental and science agencies (e.g. CSIRO, BOM) for research and/or education."
        }
      ],
      "reasoning": "Clearly explains the reef-monitoring mission, its Australian environmental rationale, the one-spacecraft choice and intended users. The operator is only described broadly as Australian facilities, and user roles and operational responsibilities are not developed in detail; this supports the lower end of Accomplished."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 97.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost ten minutes was achieved, in addition to the already frequent amount of passes."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "The most promising alternative is a ‘drag sail’ – a drag-enhancing deorbit device that deploys at the EOL."
        }
      ],
      "reasoning": "Covers launch, orbital elements, STK access results, ground station, duration and EOL, with useful screenshots and calculations. However, the launcher choice is speculative, orbital lighting and RAAN claims are weak or incorrect, payload performance is not quantified, and EOL manoeuvre capability is contradictory. Software files and several design assumptions are not supplied or validated."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "Thus, launch may need to be adjusted if the rocket is still not constructed by the proposed date."
        }
      ],
      "reasoning": "The conclusion recaps the selected mission configuration and acknowledges launch uncertainty, but mostly restates design choices. It does not draw sufficiently detailed conclusions from the reported access results, orbital analysis, or unresolved feasibility issues."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Bibliography",
          "quote": "[6] https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "DN path for orbits 1-15"
        }
      ],
      "reasoning": "The report has a recognisable structure, executive summary, headings, and generally understandable prose. Grammar and wording errors remain, figures and tables are not consistently numbered and fully captioned, and references are bare URLs with inconsistent citation numbering; Wikipedia is used as a source despite the task instructions."
    }
  ],
